from typing import List
from math import gcd

class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        m = len(target)
        full = (1 << m) - 1

        lcms = [1] * (1 << m)
        for mask in range(1, 1 << m):
            bit = mask & -mask
            i = bit.bit_length() - 1
            prev = mask ^ bit
            lcms[mask] = lcms[prev] * target[i] // gcd(lcms[prev], target[i])

        INF = 10**30
        dp = [INF] * (1 << m)
        dp[0] = 0

        for x in nums:
            cost = [0] * (1 << m)
            for mask in range(1, 1 << m):
                l = lcms[mask]
                cost[mask] = (-x) % l

            ndp = dp[:]
            for old_mask in range(1 << m):
                if dp[old_mask] == INF:
                    continue
                for add_mask in range(1, 1 << m):
                    new_mask = old_mask | add_mask
                    ndp[new_mask] = min(ndp[new_mask], dp[old_mask] + cost[add_mask])
            dp = ndp

        return dp[full]
